WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '1' HOUR THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessionized AS (SELECT id, device_code, reading_ts, temp_c, humidity, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, DATE_TRUNC('DAY', reading_ts) AS activity_day, island_id, COUNT_IF(device_code = 'DV-03') AS dv_03_events, SUM(humidity) AS total_humidity, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes FROM sessionized GROUP BY DATE_TRUNC('HOUR', reading_ts), DATE_TRUNC('DAY', reading_ts), island_id ORDER BY island_id NULLS FIRST
